import {
  JupyterFrontEnd,
  JupyterFrontEndPlugin
} from '@jupyterlab/application';

import {
  ICommandPalette,
  MainMenu
} from '@jupyterlab/mainmenu';

import {
  DocumentRegistry,
  DocumentWidget
} from '@jupyterlab/docregistry';

import { GalyleoPanel } from './GalyleoPanel'; // assuming you have this
import { galyleoFileType } from './filetypes'; // your filetype object
import { GalyleoPanelFactory } from './GalyleoPanelFactory'; // your factory

const PLUGIN_ID = 'galyleo-extension:file-commands';

const galyleoCommands: JupyterFrontEndPlugin<void> = {
  id: PLUGIN_ID,
  requires: [ICommandPalette, MainMenu],
  optional: [],
  autoStart: true,
  activate: (app: JupyterFrontEnd, palette: ICommandPalette, mainMenu: MainMenu) => {
    const { commands, serviceManager } = app;

    const fileTypeName = galyleoFileType.name;
    const fileTypeExtension = galyleoFileType.extensions[0];

    // Command IDs
    const CREATE_NEW = 'galyleo:create-new';
    const OPEN_EXISTING = 'galyleo:open-existing';
    const SAVE_ACTIVE = 'galyleo:save-active';

    // Register commands

    // 1. Create a new Galyleo document
    commands.addCommand(CREATE_NEW, {
      label: 'New Galyleo Document',
      caption: 'Create a new Galyleo document',
      execute: async () => {
        const model = await serviceManager.contents.newUntitled({
          type: 'file',
          ext: fileTypeExtension
        });

        app.commands.execute('docmanager:open', {
          path: model.path,
          factory: fileTypeName
        });
      }
    });

    // 2. Open an existing Galyleo document
    commands.addCommand(OPEN_EXISTING, {
      label: 'Open Galyleo Document...',
      caption: 'Open an existing Galyleo document',
      execute: async () => {
        await app.commands.execute('filebrowser:open-path', {
          factory: fileTypeName
        });
      }
    });

    // 3. Save the current Galyleo document
    commands.addCommand(SAVE_ACTIVE, {
      label: 'Save Galyleo Document',
      caption: 'Save the current Galyleo document',
      execute: async () => {
        const widget = app.shell.currentWidget;
        if (widget && 'context' in widget) {
          const context = (widget as DocumentWidget).context;
          if (context.model && context.path.endsWith(fileTypeExtension)) {
            await context.save();
          }
        }
      }
    });

    // Add to the File menu
    mainMenu.fileMenu.newMenu.addGroup([
      { command: CREATE_NEW }
    ], 30); // 30 = order priority (optional)

    mainMenu.fileMenu.openMenu.addGroup([
      { command: OPEN_EXISTING }
    ], 40);

    mainMenu.fileMenu.saveMenu.addGroup([
      { command: SAVE_ACTIVE }
    ], 50);

    // Optional: also add to command palette
    palette.addItem({ command: CREATE_NEW, category: 'Galyleo' });
    palette.addItem({ command: OPEN_EXISTING, category: 'Galyleo' });
    palette.addItem({ command: SAVE_ACTIVE, category: 'Galyleo' });
  }
};

export default galyleoCommands;
```

